import { customType, timestamp, uuid } from 'drizzle-orm/pg-core';

// Column builders shared by every schema file. Kept free of table imports so
// any schema module can use them without an import cycle.

/** uuid primary key generated by Postgres (`gen_random_uuid()`). */
export const id = () => uuid('id').primaryKey().defaultRandom();

export const createdAt = () =>
  timestamp('created_at', { withTimezone: true }).notNull().defaultNow();

export const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

export const timestamptz = (name: string) => timestamp(name, { withTimezone: true });

/**
 * Raw bytes. Every secret column holds a sealed envelope from `secrets.ts`
 * (plan 4.9), never plaintext.
 */
export const bytea = customType<{ data: Buffer; driverData: Buffer | Uint8Array }>({
  dataType: () => 'bytea',
  fromDriver: (value) => (Buffer.isBuffer(value) ? value : Buffer.from(value)),
});
